 const [auth,setAuth]=useState<"checking"|"ok"|"login"|"offline">("checking");const [email,setEmail]=useState("");const [password,setPassword]=useState("");const [user,setUser]=useState("");const [isPlatformAdmin,setIsPlatformAdmin]=useState(false);const [workspaceRole,setWorkspaceRole]=useState("");const [authError,setAuthError]=useState("");
 const [status,setStatus]=useState<Status|null>(null);const [budget,setBudget]=useState<Budget|null>(null);const [registry,setRegistry]=useState<Registry|null>(null);const [capabilities,setCapabilities]=useState<CapabilityMatrix|null>(null);const [loadError,setLoadError]=useState("");
 const [topic,setTopic]=useState("AI video editing tools for independent creators");const [audience,setAudience]=useState("solo creators and small teams");const [product,setProduct]=useState("");const [sources,setSources]=useState("");const [keywords,setKeywords]=useState("");const [mode,setMode]=useState("SEMI_AUTONOMOUS");const [adPlatforms,setAdPlatforms]=useState<string[]>(["meta","google_search","tiktok"]);const [adObjective,setAdObjective]=useState<"traffic"|"leads"|"sales"|"awareness">("traffic");const [adRegion,setAdRegion]=useState("US");const [adProductSummary,setAdProductSummary]=useState("");const [adLandingPageUrl,setAdLandingPageUrl]=useState("");const [adBudget,setAdBudget]=useState("0.00");const [observationPlanId,setObservationPlanId]=useState("");const [observationPlatform,setObservationPlatform]=useState("meta");const [observationCreative,setObservationCreative]=useState("meta-01");const [observationSourceType,setObservationSourceType]=useState<"manual_report"|"provider_export"|"provider_api">("manual_report");const [observationSourceUrl,setObservationSourceUrl]=useState("");const [observationImpressions,setObservationImpressions]=useState("0");const [observationClicks,setObservationClicks]=useState("0");const [observationConversions,setObservationConversions]=useState("0");const [observationSpend,setObservationSpend]=useState("0.00");const [observationCommission,setObservationCommission]=useState("0.00");const [busy,setBusy]=useState("");const [result,setResult]=useState<Result|null>(null);const [hitl,setHitl]=useState<HitlAlert|null>(null);const [verification,setVerification]=useState("");const [section,setSection]=useState("Overview");const [financeLedger,setFinanceLedger]=useState<FinanceLedger|null>(null);const [financeReconciliation,setFinanceReconciliation]=useState<FinanceReconciliation|null>(null);const [mailEvidence,setMailEvidence]=useState<FinanceList|null>(null);const [payoutThresholds,setPayoutThresholds]=useState<FinanceList|null>(null);const [financeCandidateChoice,setFinanceCandidateChoice]=useState<Record<string,string>>({});const [experimentKey,setExperimentKey]=useState("headline-test-v1");const [experimentHeadlineA,setExperimentHeadlineA]=useState("Solve the problem faster");const [experimentHeadlineB,setExperimentHeadlineB]=useState("A proven workflow for better results");const [experimentVisitorId,setExperimentVisitorId]=useState("");const [experimentResult,setExperimentResult]=useState<ExperimentResult|null>(null);const [contentAnglesText,setContentAnglesText]=useState("");const [contentAngleEvidenceText,setContentAngleEvidenceText]=useState("");const [seoAuditUrl,setSeoAuditUrl]=useState("");const [internalLinkUrls,setInternalLinkUrls]=useState("");const [xThreadSourceTitle,setXThreadSourceTitle]=useState("");const [xThreadSourceBody,setXThreadSourceBody]=useState("");const [xThreadSourceUrls,setXThreadSourceUrls]=useState("");const [purpleCowPositioning,setPurpleCowPositioning]=useState("");const [purpleCowAlternativesText,setPurpleCowAlternativesText]=useState("");const [purpleCowEvidenceNotesText,setPurpleCowEvidenceNotesText]=useState("");
 const refresh=useCallback(async()=>{try{const [a,b,c,d]=await Promise.all([apiFetch<Status>("/api/status"),apiFetch<Budget>("/api/resource-budget"),apiFetch<Registry>("/api/integrations"),apiFetch<CapabilityMatrix>("/api/capabilities")]);setStatus(a);setBudget(b);setRegistry(c);setCapabilities(d);setLoadError("")}catch(e){setLoadError(e instanceof Error?e.message:"The API is not reachable")}},[]);
 const checkAuth=useCallback(async()=>{try{const r=await apiFetch<{user?:{email?:string;is_admin?:boolean;workspace_role?:string}}>("/api/auth/me");setUser(r.user?.email||"local operator");setIsPlatformAdmin(r.user?.is_admin===true);setWorkspaceRole(r.user?.workspace_role||"");setAuth("ok");setAuthError("")}catch(e){const msg=e instanceof Error?e.message:"Could not connect";setIsPlatformAdmin(false);setWorkspaceRole("");setAuth(msg.startsWith("401")?"login":"offline");setAuthError(msg)}},[]);
 useEffect(()=>{try{const key="omni-affiliate-os-experiment-visitor";let id=window.localStorage.getItem(key);if(!id){id=window.crypto.randomUUID();window.localStorage.setItem(key,id)}setExperimentVisitorId(id)}catch{setExperimentVisitorId(window.crypto.randomUUID())}},[]);useEffect(()=>{void checkAuth()},[checkAuth]);useEffect(()=>{if(auth!=="ok")return;void refresh();const id=window.setInterval(()=>void refresh(),15000);return()=>window.clearInterval(id)},[auth,refresh]);
 const operate=useCallback(async(label:string,path:string,payload?:unknown,method="POST")=>{setBusy(label);setLoadError("");try{const data=await apiFetch(path,{method,body:payload===undefined?undefined:JSON.stringify(payload)});setResult({label,data,time:new Date().toISOString()});if(["/api/status","/api/integrations","/api/resource-budget"].includes(path))void refresh();return data}catch(e){setLoadError(e instanceof Error?e.message:"Operation failed");throw e}finally{setBusy("")}},[refresh]);
 const login=async(e:FormEvent)=>{e.preventDefault();setBusy("login");setAuthError("");try{const r=await apiFetch<{user?:{email?:string;is_admin?:boolean;workspace_role?:string}}>("/api/auth/login",{method:"POST",body:JSON.stringify({email,password})});setUser(r.user?.email||email);setIsPlatformAdmin(r.user?.is_admin===true);setWorkspaceRole(r.user?.workspace_role||"");setPassword("");setAuth("ok")}catch(e){setIsPlatformAdmin(false);setWorkspaceRole("");setAuthError(e instanceof Error?e.message:"Login failed")}finally{setBusy("")}};
 const run=async()=>{try{await operate("Start S1–S8","/api/workflows/run",{workflow_name:"full_flywheel",execution_mode:mode,state:{topic,audience,trend_query:topic,scout_trends:true,build_blog:true,run_learning:true,...(product.trim()?{product:{name:product.trim()}}:{}),source_urls:sources.split("\n").map(x=>x.trim()).filter(Boolean),...(keywords.trim()?{keywords:keywords.split("\n").map(x=>x.trim()).filter(Boolean)}:{})}})}catch{/* Error already rendered. */}};
