 const draftXThread=async(e:FormEvent)=>{e.preventDefault();const title=xThreadSourceTitle.trim();const body=xThreadSourceBody.trim();if(title.length<3||body.length<80){setLoadError("Provide a source title and at least 80 characters of source text.");return}const source_urls=xThreadSourceUrls.split("\n").map(x=>x.trim()).filter(Boolean);try{await operate("Draft X thread","/api/content/atomize",{source_title:title,source_body:body,platforms:["x_thread"],source_urls})}catch{/* Error already rendered. */}};
 const runPurpleCowAudit=async(e:FormEvent)=>{e.preventDefault();const positioning_statement=purpleCowPositioning.trim();const lines=purpleCowAlternativesText.split("\n").map(x=>x.trim()).filter(Boolean);if(lines.length<1||lines.length>10){setLoadError("Provide between one and ten alternative positioning statements.");return}const alternatives=lines.map((line,index)=>{const split=line.indexOf("|");if(split<0)return{name:"Alternative "+(index+1),positioning_statement:line};return{name:line.slice(0,split).trim(),positioning_statement:line.slice(split+1).trim()}});if(alternatives.some(x=>x.name.length<2||x.positioning_statement.length<5)){setLoadError("Format each alternative as Name | positioning statement.");return}const evidence_notes=purpleCowEvidenceNotesText.split("\n").map(x=>x.trim()).filter(Boolean);try{await operate("Audit differentiation","/api/research/purple-cow-audit",{offer_name:product.trim()||topic.trim(),target_audience:audience.trim(),positioning_statement,alternatives,evidence_notes})}catch{/* Error already rendered. */}};
 const runInternalLinkAnalysis=async(e:FormEvent)=>{e.preventDefault();const urls=internalLinkUrls.split("\n").map(x=>x.trim()).filter(Boolean);if(urls.length<2){setLoadError("Enter at least two public page URLs from the same site.");return}if(urls.length>12){setLoadError("Analyze at most 12 pages at once.");return}try{await operate("Recommend internal links","/api/research/internal-links",{urls,max_suggestions_per_page:5})}catch{/* Error already rendered. */}};
 const runSeoAudit=async(e:FormEvent)=>{e.preventDefault();const url=seoAuditUrl.trim();if(!url){setLoadError("Enter the public page URL to audit.");return}try{await operate("Audit public page","/api/research/seo-audit",{url})}catch{/* Error already rendered. */}};
 const rankContentAngles=async(e:FormEvent)=>{e.preventDefault();const angles=contentAnglesText.split("\n").map(x=>x.trim()).filter(Boolean);if(!topic.trim()||topic.trim().length<3){setLoadError("Enter a topic with at least three characters before ranking angles.");return}if(angles.length===0){setLoadError("Enter at least one content angle, one per line.");return}const evidence=contentAngleEvidenceText.split("\n");const candidates=angles.map((angle,index)=>({angle,evidence_facts:(evidence[index]||"").split(";").map(x=>x.trim()).filter(Boolean)}));try{await operate("Rank content angles","/api/content/angles/rank",{topic,audience,candidates})}catch{/* Error already rendered. */}};
